/** A condensed placeholder baked into a Function-name template. */
export type VmixFamilyParam =
  | { id: string; kind: "int"; min: number; max: number; label?: string }
  | { id: string; kind: "enum"; values: string[]; label?: string };

export interface VmixShortcut {
  /** Function name. May contain {placeholders} expanded via `family`. */
  fn: string;
  category: VmixCategory;
  description: string;
  /** Query args read besides any family placeholders, in vMix order. */
  params: VmixParamId[];
  /** Present when `fn` is a condensed template. */
  family?: VmixFamilyParam[];
}

