/**
 * Resolve a (possibly templated) shortcut into a concrete vMix Function
 * name by substituting the chosen family values.
 *   buildVmixFunction("OverlayInput{ch}", { ch: 2 }) === "OverlayInput2"
 */
export function buildVmixFunction(
  fn: string,
  selection: Record<string, string | number> = {},
): string {
  return fn.replace(/\{(\w+)\}/g, (_, id) => {
    const v = selection[id];
    if (v === undefined) {
      throw new Error(`buildVmixFunction: missing family value "${id}" for "${fn}"`);
    }
    return String(v);
  });
}

